    "tool_started",
    "tool_completed",
    "tool_call",
    "tool_call_result",
    "function_call",
    "function_call_output",
    "local_shell_call",
    "web_search_call",
    "custom_tool_call",
    "mcp_tool_call",
}

REDACTIONS = [
    (
        re.compile(
            r"(?i)(api[_-]?key|token|password|secret|authorization)\s*[:=]\s*['\"]?([^\s'\"]+)"
        ),
        r"\1=***",
    ),
    (re.compile(r"sk-or-v1-[a-zA-Z0-9_-]{10,}"), "sk-or-v1-***"),
    (re.compile(r"sk-[a-zA-Z0-9_-]{10,}"), "sk-***"),
    (
        re.compile(
            r"-----BEGIN [A-Z ]*PRIVATE KEY-----[\s\S]*?-----END [A-Z ]*PRIVATE KEY-----"
        ),
        "[REDACTED PRIVATE KEY]",
    ),
    (
        re.compile(
            r'(?i)(\\?"[a-z_]*(?:private_?key|secret|password|passwd|token|api_?key|'
            r"sealed_?id|credential|shortids?)[a-z_]*\\?\"\s*:\s*\\?\")([^\"\\]+)"
        ),
        r"\1***",
    ),
    (
        re.compile(r"\b(?:SID1|OIA1|U0lEMQ|T0lBMQ)[A-Za-z0-9+/=_.:-]{16,}"),
        "[REDACTED CREDENTIAL]",
    ),
    (
        re.compile(r"(?i)(authorization|x-api-key|api-key)\s*[:=]\s*\S+"),
        r"\1: ***",
    ),
]


def redact(text: str) -> str:
    out = text
    for pattern, repl in REDACTIONS:
        out = pattern.sub(repl, out)
    return out


def iso(ts: float | None) -> str | None:
    if ts is None:
        return None
    try:
        return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(ts))
    except (OverflowError, OSError, ValueError):
        return None


def note_ts(value, acc: dict) -> None:
    if isinstance(value, str):
        if len(value) >= 20 and value[0:4] == "2026" and "T" in value[10:12]:
            acc_ts = value
            if acc["first_raw"] is None or acc_ts < acc["first_raw"]:
                acc["first_raw"] = acc_ts
            if acc["last_raw"] is None or acc_ts > acc["last_raw"]:
                acc["last_raw"] = acc_ts
        return
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        n = float(value)
        if n > 1e12:
            n /= 1000.0
        if 1700000000 < n < 2000000000:
            if acc["first_epoch"] is None or n < acc["first_epoch"]:
                acc["first_epoch"] = n
            if acc["last_epoch"] is None or n > acc["last_epoch"]:
                acc["last_epoch"] = n


def tool_name(obj: dict) -> str | None:
    for key in ("name", "tool_name", "toolName", "tool", "method"):
        value = obj.get(key)
        if isinstance(value, str) and value and len(value) < 160:
            return value
    return None


def walk_obj(obj, acc: dict, depth: int = 0) -> None:
    if depth > 8:
        return
    if isinstance(obj, dict):
        kind = obj.get("type")
        if isinstance(kind, str) and (
            kind in TOOL_TYPES or "tool" in kind.lower() or kind.endswith("_call")
        ):
            acc["tools"] += 1
            name = tool_name(obj)
            if name:
                acc["names"][name] += 1
        calls = obj.get("tool_calls") or obj.get("toolCalls")
        if isinstance(calls, list):
            acc["tools"] += len(calls)
            for call in calls:
                if isinstance(call, dict):
                    name = tool_name(call)
                    fn = call.get("function")
                    if name is None and isinstance(fn, dict):
                        name = tool_name(fn)
                    if name:
                        acc["names"][name] += 1
        for key in (
            "timestamp",
            "created_at",
            "createdAt",
            "time",
            "lastUpdatedAt",
            "updatedAt",
        ):
            if key in obj:
                note_ts(obj[key], acc)
        for value in obj.values():
            if isinstance(value, (dict, list)):
                walk_obj(value, acc, depth + 1)
    elif isinstance(obj, list):
        for item in obj:
            if isinstance(item, (dict, list)):
                walk_obj(item, acc, depth + 1)


def new_acc() -> dict:
    return {
        "records": 0,
        "tools": 0,
        "names": Counter(),
        "first_raw": None,
        "last_raw": None,
        "first_epoch": None,
        "last_epoch": None,
        "bytes": 0,
    }


def span(acc: dict) -> tuple[str | None, str | None]:
    first = acc["first_raw"] or iso(acc["first_epoch"])
    last = acc["last_raw"] or iso(acc["last_epoch"])
    return first, last


def denied(path: Path) -> bool:
    name = path.name.lower()
    if name.endswith(".lock") or ".lock." in name:
        return True
    if path.suffix.lower() in {".pem", ".key", ".p12", ".sqlite", ".db", ".wal", ".shm"}:
        return True
    markers = (
        "auth.json",
        "credential",
        "credentials",
        ".env",
        "oauth",
        "cookie",
        "secret",
        "id_rsa",
        "id_ed25519",
    )
    return any(marker in name for marker in markers)


def copy_text(src: Path, dest: Path, acc: dict, parse_jsonl: bool) -> None:
    dest.parent.mkdir(parents=True, exist_ok=True)
    tmp = dest.with_suffix(dest.suffix + ".partial")
    with src.open("r", errors="replace") as inp, tmp.open("w", encoding="utf-8") as out:
        for line in inp:
            red = redact(line)
            out.write(red)
            acc["bytes"] += len(red.encode("utf-8", "replace"))
            if not parse_jsonl:
                acc["records"] += 1
                continue
            stripped = line.strip()
            if not stripped:
                continue
            acc["records"] += 1
            try:
                obj = json.loads(stripped)
            except json.JSONDecodeError:
                continue
            walk_obj(obj, acc)
    os.chmod(tmp, 0o600)
    tmp.replace(dest)


def rel_under(path: Path, root: Path) -> Path:
    try:
        return path.relative_to(root)
    except ValueError:
        return Path(path.name)


class Archive:
    def __init__(self) -> None:
        self.rows: list[dict] = []
        self.names: dict[str, Counter] = defaultdict(Counter)
        self.gaps: list[dict] = []
        self.files = 0
        self.bytes = 0

    def add_row(self, source: str, kind: str, origin: str, archive: str, acc: dict, extra: dict | None = None) -> None:
        first, last = span(acc)
        row = {
            "source": source,
            "kind": kind,
            "origin": origin,
            "archive": archive,
            "bytes": acc["bytes"],
            "records": acc["records"],
            "tool_events": acc["tools"],
            "first": first,
            "last": last,
        }
        if extra:
            row.update(extra)
        self.rows.append(row)
        self.names[source].update(acc["names"])
        self.files += 1
        self.bytes += acc["bytes"]

    def copy_file(self, source: str, src: Path, dest_rel: str, kind: str, parse_jsonl: bool) -> None:
        if not src.is_file() or denied(src):
            return
        if src.stat().st_size > 800_000_000:
            self.gaps.append(
                {"source": source, "path": str(src), "reason": "skipped file larger than 800MB"}
            )
            return
        dest = OUT / dest_rel
        acc = new_acc()
        copy_text(src, dest, acc, parse_jsonl)
        self.add_row(source, kind, str(src), dest_rel, acc)

    def mtime_ok(self, path: Path) -> bool:
        try:
            return path.stat().st_mtime >= CUTOFF
        except OSError:
            return False


def collect_grok(arc: Archive) -> None:
    root = HOME / ".grok" / "sessions"
    wanted = {
        "chat_history.jsonl",
        "events.jsonl",
        "updates.jsonl",
        "rewind_points.jsonl",
        "summary.json",
    }
    session_dirs: set[Path] = set()
    if root.is_dir():
        for dirpath, dirnames, filenames in os.walk(root):
            dirnames[:] = [d for d in dirnames if d not in {"node_modules", "terminal"}]
            parent = Path(dirpath)
            for name in filenames:
                if name in wanted and arc.mtime_ok(parent / name):
                    session_dirs.add(parent)
    copied = 0
    for parent in sorted(session_dirs):
        for name in sorted(wanted):
            src = parent / name
            if not src.is_file():
                continue
            dest = Path("grok") / rel_under(src, root)
            arc.copy_file("grok", src, str(dest), name, name.endswith(".jsonl"))
            copied += 1
    sandbox = root / "sandbox-events.jsonl"
    if sandbox.is_file() and arc.mtime_ok(sandbox):
        arc.copy_file("grok", sandbox, "grok/sandbox-events.jsonl", "sandbox-events", True)
    arc.gaps.append(
        {
            "source": "grok",
            "reason": f"{len(session_dirs)} session directories had files written on or after 2026-10-26; {copied} conversation/tool files copied",
        }
    )


def collect_jsonl_tree(arc: Archive, source: str, root: Path, dest_root: str) -> int:
    count = 0
    if not root.is_dir():
        arc.gaps.append({"source": source, "path": str(root), "reason": "store missing"})
        return 0
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d not in {"node_modules", ".git", "Cache"}]
        for name in filenames:
            if not name.endswith(".jsonl"):
                continue
            src = Path(dirpath) / name
            if denied(src) or not arc.mtime_ok(src):
                continue
            dest = Path(dest_root) / rel_under(src, root)
            arc.copy_file(source, src, str(dest), "jsonl", True)
            count += 1
    return count


