def collect_hermes(arc: Archive) -> None:
    db = HOME / ".hermes" / "state.db"
    if not db.is_file():
        arc.gaps.append({"source": "hermes", "reason": "state.db missing"})
        return
    out_dir = OUT / "hermes" / "sessions"
    out_dir.mkdir(parents=True, exist_ok=True)
    con = sqlite3.connect(f"file:{db}?mode=ro", uri=True)
    con.row_factory = sqlite3.Row
    sessions = list(
        con.execute(
            """
            SELECT s.id, s.source, s.display_name, s.model, s.started_at, s.ended_at
            FROM sessions s
            WHERE EXISTS (
              SELECT 1 FROM messages m
              WHERE m.session_id = s.id AND m.timestamp >= ?
            )
            ORDER BY s.started_at
            """,
            (CUTOFF,),
        )
    )
    for session in sessions:
        sid = session["id"]
        dest = out_dir / f"{sid}.jsonl"
        acc = new_acc()
        with dest.open("w", encoding="utf-8") as out:
            header = {
                "type": "session",
                "id": sid,
                "source": session["source"],
                "display_name": session["display_name"],
                "model": session["model"],
                "started_at": session["started_at"],
                "ended_at": session["ended_at"],
            }
            line = redact(json.dumps(header, default=str) + "\n")
            out.write(line)
            acc["bytes"] += len(line.encode())
            acc["records"] += 1
            note_ts(session["started_at"], acc)
            for message in con.execute(
                """
                SELECT id, role, content, tool_call_id, tool_calls, tool_name,
                       timestamp, finish_reason
                FROM messages
                WHERE session_id = ? AND timestamp >= ?
                ORDER BY timestamp, id
                """,
                (sid, CUTOFF),
            ):
                payload = {key: message[key] for key in message.keys()}
                raw_calls = payload.get("tool_calls")
                if isinstance(raw_calls, str):
                    try:
                        payload["tool_calls"] = json.loads(raw_calls)
                    except json.JSONDecodeError:
                        pass
                line = redact(json.dumps(payload, default=str) + "\n")
                out.write(line)
                acc["bytes"] += len(line.encode())
                acc["records"] += 1
                walk_obj(payload, acc)
                if payload.get("tool_name"):
                    acc["tools"] += 1
                    acc["names"][str(payload["tool_name"])] += 1
                note_ts(payload.get("timestamp"), acc)
        os.chmod(dest, 0o600)
        arc.add_row(
            "hermes",
            "session",
            str(db),
            str(dest.relative_to(OUT)),
            acc,
            {"session_id": sid, "title": session["display_name"]},
        )
    dumps = HOME / ".hermes" / "sessions"
    dump_count = 0
    if dumps.is_dir():
        for path in sorted(dumps.glob("request_dump_*.json")):
            if arc.mtime_ok(path):
                arc.copy_file(
                    "hermes",
                    path,
                    f"hermes/request-dumps/{path.name}",
                    "request_dump",
                    False,
                )
                dump_count += 1
    arc.gaps.append(
        {
            "source": "hermes",
            "reason": f"{len(sessions)} sessions with messages on or after cutoff; {dump_count} request dumps copied. System prompt bodies were not copied.",
        }
    )


def composer_epochs(obj) -> list[float]:
    found: list[float] = []

    def walk(value, depth: int) -> None:
        if depth > 5:
            return
        if isinstance(value, dict):
            for key, item in value.items():
                if key in {
                    "createdAt",
                    "lastUpdatedAt",
                    "lastReadAtMs",
                    "conversationCheckpointLastUpdatedAt",
                    "unfinishedRunAt",
                } and isinstance(item, (int, float)):
                    n = float(item)
                    found.append(n / 1000.0 if n > 1e12 else n)
                elif isinstance(item, (dict, list)):
                    walk(item, depth + 1)
        elif isinstance(value, list):
            for item in value[:30]:
                walk(item, depth + 1)

    walk(obj, 0)
    return found


def collect_cursor_db(arc: Archive) -> None:
    db = HOME / ".config" / "Cursor" / "User" / "globalStorage" / "state.vscdb"
    if not db.is_file():
        arc.gaps.append({"source": "cursor", "reason": "global state.vscdb missing"})
        return
    con = sqlite3.connect(f"file:{db}?mode=ro", uri=True)
    chosen: dict[str, dict] = {}
    for key, value in con.execute(
        "SELECT key, value FROM cursorDiskKV WHERE key LIKE 'composerData:%'"
    ):
        if isinstance(value, bytes):
            value = value.decode("utf-8", "replace")
        try:
            obj = json.loads(value)
        except json.JSONDecodeError:
            continue
        epochs = [n for n in composer_epochs(obj) if n > 1700000000]
        if not epochs or max(epochs) < CUTOFF:
            continue
        cid = key.split("composerData:", 1)[1]
        chosen[cid] = obj
    out_dir = OUT / "cursor" / "composers"
    for cid, obj in sorted(chosen.items()):
        dest = out_dir / cid / "composer.jsonl"
        dest.parent.mkdir(parents=True, exist_ok=True)
        acc = new_acc()
        with dest.open("w", encoding="utf-8") as out:
            header = {
                "type": "composer",
                "composerId": obj.get("composerId") or cid,
                "name": obj.get("name"),
                "createdAt": obj.get("createdAt"),
                "lastUpdatedAt": obj.get("lastUpdatedAt"),
                "isAgentic": obj.get("isAgentic"),
            }
            line = redact(json.dumps(header, default=str) + "\n")
            out.write(line)
            acc["records"] += 1
            acc["bytes"] += len(line.encode())
            walk_obj(header, acc)
            like = f"bubbleId:{cid}:%"
            for bkey, raw in con.execute(
                "SELECT key, value FROM cursorDiskKV WHERE key LIKE ?",
                (like,),
            ):
                if isinstance(raw, bytes):
                    raw = raw.decode("utf-8", "replace")
                try:
                    bubble = json.loads(raw)
                except json.JSONDecodeError:
                    bubble = {"raw": raw[:2000]}
                record = {"type": "bubble", "key": bkey, "bubble": bubble}
                line = redact(json.dumps(record, default=str) + "\n")
                out.write(line)
                acc["records"] += 1
                acc["bytes"] += len(line.encode())
                walk_obj(record, acc)
        os.chmod(dest, 0o600)
        arc.add_row("cursor", "composer", str(db), str(dest.relative_to(OUT)), acc, {"composer_id": cid, "title": obj.get("name")})
    arc.gaps.append(
        {
            "source": "cursor",
            "reason": f"{len(chosen)} composer records in global state.vscdb have a timestamp on or after 2026-10-26. The 1.6GB database itself was not copied.",
        }
    )


def collect_sqlite_absence(arc: Archive) -> None:
    for source, db in (
        ("opencode", HOME / ".local/share/opencode/opencode.db"),
        ("kilo", HOME / ".local/share/kilo/kilo.db"),
    ):
        if not db.is_file():
            arc.gaps.append({"source": source, "reason": "database missing"})
            continue
        con = sqlite3.connect(f"file:{db}?mode=ro", uri=True)
        count = con.execute(
            "SELECT count(*) FROM session WHERE time_updated >= ?",
            (CUTOFF_MS,),
        ).fetchone()[0]
        latest = con.execute("SELECT max(time_updated) FROM session").fetchone()[0]
        arc.gaps.append(
            {
                "source": source,
                "reason": f"{count} sessions updated on or after cutoff. Latest session update {iso((latest or 0) / 1000.0)}. Database not copied because it contains a credential table.",
            }
        )


